//MESH_BEGIN
u: 0, pi/2, 40
v: -1, 1, 40
//MESH_END

// Superficie di Brieskorn-Pham:  z1^a + z2^b = 1,  con z1,z2 complessi.
// Generalizza la sezione di Calabi-Yau: li' i due esponenti erano UGUALI (la
// quintica di Fermat, a = b = n), qui sono INDIPENDENTI e governati da due
// slider distinti. Con a != b la figura perde la simmetria di scambio fra le
// due coordinate complesse e cambia genere: e' una famiglia topologicamente
// diversa, non una deformazione della stessa forma.
//
// Per ogni coppia di radici (k1 di ordine a, k2 di ordine b) c'e' una patch:
//   z1 = e^(2 pi i k1/a) * (cos w)^(2/a)
//   z2 = e^(2 pi i k2/b) * (sin w)^(2/b)     con w = u + i v
//
// SUPERFICIE 4D VERA: Im(z2) esce come componente w del vec4, quindi proiezione
// e rotazioni 4D restano all'interfaccia (come nel preset "Calabi-Yau", non
// nella variante "3D" che mescola la quarta coordinata dentro lo script).
//
// GRIGLIE STATICHE: si leggono al Run, quindi dichiariamo il massimo 49 = 7x7 e
// scartiamo le eccedenti nel cutout. Gli indici NON sono in base 7 fissa: si
// calcolano sulla griglia viva (k1 = mesh % a, k2 = mesh / a), cosi' le patch
// superstiti sono le prime a*b e il contatore delle mesh non offre mai numeri
// che puntano a patch scartate.

A := int(2,7);          // esponente di z1: slider a scatti interi
B := int(2,7);          // esponente di z2: slider a scatti interi
MESH_VISIBLE := A*B;    // quante griglie sopravvivono al cutout

// clamp: protegge la geometria se lo slider esce dal dominio dichiarato.
// Va replicato IDENTICO nel blocco CUTOUT, o le patch vive non coincidono.
float na = clamp(floor(A + 0.5), 2.0, 7.0);
float nb = clamp(floor(B + 0.5), 2.0, 7.0);

// NUMERAZIONE COMPATTA: gli indici si calcolano sulla griglia VIVA (na x nb),
// non sulla base fissa 7. Cosi' le patch superstiti sono le PRIME na*nb in
// ordine di mesh, e il contatore dell'interfaccia (che mappa numero -> mesh
// come value()-1) punta sempre a una patch che si vede davvero.
// Con la vecchia base 7 le vive erano 0,1,2, 7,8,9, 14... e dal quarto numero
// in poi il selettore cadeva su patch scartate dal cutout: slider inerti.
// Le COPPIE (k1,k2) disegnate sono le stesse di prima: cambia l'indice che le
// porta, non la figura.
float k1 = mod(float(mesh), na);
float k2 = floor(float(mesh) / na);

float pa = 2.0 / na;
float pb = 2.0 / nb;

// w = u + i v;  cos(w) e sin(w) complessi
vec2 cw = vec2( cos(u) * cosh(v), -sin(u) * sinh(v));
vec2 sw = vec2( sin(u) * cosh(v),  cos(u) * sinh(v));

// Potenza complessa in forma polare. Sul dominio dichiarato Re(cos w) e
// Re(sin w) restano POSITIVE: l'argomento sta in (-pi/2, pi/2), lontano dal
// salto di atan, quindi niente taglio di ramo ne' cuciture fra patch.
float rc = safePow(length(cw), pa);
float tc = pa * atan(cw.y, cw.x);
float rs = safePow(length(sw), pb);
float ts = pb * atan(sw.y, sw.x);

// Radici dell'unita': e^(2 pi i k1/a) e e^(2 pi i k2/b) -- ordini DIVERSI.
float t1 = 2.0 * pi * k1 / na;
float t2 = 2.0 * pi * k2 / nb;

vec2 z1 = rc * vec2(cos(tc + t1), sin(tc + t1));
vec2 z2 = rs * vec2(cos(ts + t2), sin(ts + t2));

// (Re z1, Re z2, Im z1) in R^3 + Im z2 come quarta coordinata.
// Lo slider C scala la quarta dimensione: a C=0 la figura collassa in R^3
// (utile per confrontarla con la vista 3D), a C=1 e' la superficie 4D piena.
return vec4(z1.x, z2.x, z1.y, C * z2.y);

//CUTOUT_BEGIN
// Scarta la CODA: con la numerazione compatta del corpo le patch vive sono le
// prime ca*cb, quindi basta un confronto sull'indice. Il clamp resta replicato
// identico al corpo (na/nb), o le patch vive non coincidono.
float ca = clamp(floor(A + 0.5), 2.0, 7.0);
float cb = clamp(floor(B + 0.5), 2.0, 7.0);
return float(mesh) > ca * cb - 0.5;
//CUTOUT_END
